package views

import "github.com/kmlebedev/clickhouse-import-rosstat/util"

// dcfAssumptionsView — единственный выход DCF-модели, который видит агент:
// NPV каждого актива по комбинации (deck, contour). Строки пишет импортёр
// dcf_engine в nav_by_asset; сырая таблица агенту не выдана, читается только
// эта витрина — поэтому вся семантика «что значит число» обязана лежать в
// комментариях колонок, а не в коде импортёра.
//
// Оконный итог nav_total_usd_mln считается в самой витрине, а не отдельной
// строкой-итогом: строка на (deck, contour) с asset = NULL сломала бы гранулярность
// «одна строка = один актив» и на ней споткнулся бы любой фильтр по активу.
// PARTITION BY включает run_id, deck и contour — сложив по одному run_id без
// разбивки по контурам, агент получил бы сумму промышленного и локального NAV
// (это удвоение, а не агрегат), а сложив без deck — смесь трёх ценовых сценариев,
// что прямо запрещено правилом роадмапа §13.4: P/NAV сравнивается только на
// одинаковом deck.
//
// StageHatcut в nav_by_asset всегда NULL на этой итерации (стадийные haircut'ы
// для ресурсов вне LOM — отдельный пункт роадмапа, §13.3), и колонка оставлена
// в выдаче намеренно: агент должен видеть «дисконт за стадию не применён», а не
// гадать, есть ли он где-то ещё.
var dcfAssumptionsView = util.View{
	Name:   "v_dcf_assumptions",
	Tables: []string{"nav_by_asset"},
	Select: `SELECT
    run_id,
    deck,
    contour,
    asset,
    npv_usd_mln,
    discount_rate,
    stage_haircut,
    sum(npv_usd_mln) OVER (PARTITION BY run_id, deck, contour) AS nav_total_usd_mln
FROM nav_by_asset FINAL`,
	Comment: "NPV активов DCF-модели Полюса: одна строка на (run_id, deck, contour, asset) плюс суммарный NAV по run'у, ценовому дек'у и контуру ставки в каждой строке. Источник — nav_by_asset, который наполняет импортёр dcf_engine; сырая таблица агенту не выдана. Складывать npv_usd_mln между контурами или дека'ми нельзя: это разные ставки и разные ценовые сценарии, сравнивать их можно только по отдельности (roadmap §13.4). Замыкание полного NAV акции (минус net debt и корпоративные затраты плюс опционность ресурсов) на этой итерации не считается — витрина даёт только сумму NPV рудников",
	Columns: map[string]string{
		"run_id":            "Идентификатор прогона модели (UUID): связывает строку с model_runs, где лежат входы (цены, курс, ИПЦ) и допущения этого прогона. Разные прогоны не смешивать — сравнивать и суммировать можно только строки одного run_id",
		"deck":              "Ценовой дек: 'spot_flat' — плоский текущий спот; 'consensus_lt' — консенсус с долгосрочным якорем ниже спота; 'own_scenario' — собственный сценарий с LT-хвостом к обоснованной оценке. Три дека нужны затем, чтобы разделить «сколько стоит рудник при сегодняшней цене» и «сколько он стоит при цене, которую закладывают sell-side и buy-side» (roadmap §13.4); каждый run считается на всех трёх. Суммировать или сравнивать NPV по разным дека'м нельзя: это разные ценовые сценарии, а не разбивка целого на части",
		"contour":           "Контур ставки дисконтирования: 'industrial' — 5% real USD плюс страновая и стадийная надбавки, сопоставим с глобальным P/NAV и с оценками по мировой практике (для золотодобычи CAPM/WACC не применяется — бета сектора около нуля или отрицательна); 'local' — кривая ОФЗ плюс премии, объясняет локальную цену акции. Два контура — это две разные ставки, и сложение NPV по ним даст удвоение NAV; сравнивать их между собой нужно как «глобальная оценка против локальной» (roadmap §13.1)",
		"asset":             "Актив (месторождение): 'OLIMPIADA', 'BLAGODATNOYE', 'TITIMUKHTA', 'VERNINSKOYE2', 'ALLUVIALS', 'KURANAKH', 'ZAPADNOYE', 'NATALKA', 'Sukhoi Log'. Соответствует планам из mine_plans — NPV считается по life-of-mine плану актива, а не по компании целиком. Набор активов задаёт импортёр планов, а не витрина: пустая выдача означает «план актива ещё не загружен в mine_plans»",
		"npv_usd_mln":       "NPV актива по его LOM-плану в млн USD, дисконтированный по ставке этого контура. В конце LOM учтён ОТРИЦАТЕЛЬНЫЙ хвост закрытия (рекультивация, выходные пособия) — перпетуити-терминала у рудника нет (roadmap §13.3). Значение относится к одному (deck, contour) и вне этой тройки смысла не имеет; налоги и НДПИ с надбавкой уже внутри потока",
		"discount_rate":     "Ставка дисконтирования этого контура, доли (0.05 = 5%), применённая к потоку актива. Стоит в строке рядом с NPV затем, чтобы агент видел ставку, по которой посчитано именно это число, — иначе два контура различались бы только именем, а сопоставление с зарубежными P/NAV было бы невозможно",
		"stage_haircut":     "Дисконт за стадию проекта (construction/DFS/PEA) для ресурсов вне LOM; NULL — стадийные haircut'ы на этой итерации не применяются, строка рудника считается полным NPV LOM, а опционность ресурсов вне LOM (в том числе Сухой Лог) в NAV пока не входит. NULL здесь — это «дисконт не применён», а не «нулевой дисконт»: видеть это различие обязательно, иначе NPV читается как готовый NAV с опционностью (roadmap §13.3)",
		"nav_total_usd_mln": "Сумма npv_usd_mln по всем активам ЭТОГО (run_id, deck, contour) — суммарный NAV рудников, млн USD. Число повторяется в каждой строке группы, поэтому при выборке нескольких активов его нельзя суммировать повторно. Net debt, корпоративные затраты и опционность ресурсов сюда ещё НЕ вычтены: это NAV рудников, а не NAV акции (сравнение с котировкой по этой колонке некорректно)",
	},
}
